/* highlight.js fallback sufficient for packaged/offline chat rendering. */
(function () {
  if (window.hljs) return;
  function esc(s) {
    return String(s || "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;");
  }
  window.hljs = {
    getLanguage: function () { return true; },
    highlight: function (code) { return { value: esc(code) }; },
    highlightAuto: function (code) { return { value: esc(code) }; },
    highlightElement: function () {},
  };
})();
